BEGIN;
CREATE SCHEMA IF NOT EXISTS revenue;
CREATE TABLE IF NOT EXISTS revenue.recognized_income(income_id uuid PRIMARY KEY,source_system text NOT NULL,source_reference text NOT NULL,asset_id uuid NOT NULL REFERENCES pooling.asset_position(asset_id),pool_id text NOT NULL REFERENCES pooling.pool(pool_id),business_date date NOT NULL,currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),amount numeric(30,12) NOT NULL CHECK(amount<>0),cash_status text NOT NULL CHECK(cash_status IN('ACCRUED','RECEIVED')),realization_status text NOT NULL CHECK(realization_status IN('REALIZED','UNREALIZED')),income_type text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(source_system,source_reference,income_type));
CREATE TABLE IF NOT EXISTS revenue.income_adjustment(adjustment_id uuid PRIMARY KEY,income_id uuid NOT NULL REFERENCES revenue.recognized_income(income_id),amount numeric(30,12) NOT NULL CHECK(amount<>0),reason text NOT NULL CHECK(length(trim(reason))>=10),approval_id text NOT NULL REFERENCES workflow.approval_action(idempotency_key),business_date date NOT NULL,actor_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE OR REPLACE FUNCTION revenue.reject_income_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'Recognized income and adjustments are append-only';END;$$;DROP TRIGGER IF EXISTS recognized_income_immutable ON revenue.recognized_income;CREATE TRIGGER recognized_income_immutable BEFORE UPDATE OR DELETE ON revenue.recognized_income FOR EACH ROW EXECUTE FUNCTION revenue.reject_income_mutation();DROP TRIGGER IF EXISTS income_adjustment_immutable ON revenue.income_adjustment;CREATE TRIGGER income_adjustment_immutable BEFORE UPDATE OR DELETE ON revenue.income_adjustment FOR EACH ROW EXECUTE FUNCTION revenue.reject_income_mutation();
COMMIT;
